<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
final class TaskAgentRemindersV1ContractTest extends TestCase
{
 public function testReminderWorkflowsUseCanonicalSystemServices():void{$root=dirname(__DIR__,2);$context=file_get_contents($root.'/includes/task-agent-context.php');$api=file_get_contents($root.'/api/agents/runtime.php');$script=file_get_contents($root.'/assets/js/multi-agent-runtime.js');$actions=file_get_contents($root.'/includes/personal-agent/actions.php');foreach([$context,$api,$script,$actions] as $value)self::assertIsString($value);foreach(['mg_task_agent_reminder_payload',"'action'=>'save_reminder'",'mg_task_agent_reminder_cards',"'action'=>'manage_reminder'",'No gift, message, purchase, or delivery is scheduled.'] as $marker)self::assertStringContainsString($marker,$context);self::assertStringContainsString("\$action==='create_reminder'",$api);self::assertStringContainsString('mg_personal_agent_create_reminder',$api);self::assertStringContainsString("\$action==='update_reminder_status'",$api);self::assertStringContainsString('mg_personal_agent_update_reminder_status',$api);self::assertStringContainsString("'used_ai'=>false",$api);self::assertStringContainsString("'response_source'=>'system_action'",$api);foreach(['data-save-agent-reminder','data-reminder-status',"action:'create_reminder'","action:'update_reminder_status'"] as $marker)self::assertStringContainsString($marker,$script);self::assertStringContainsString('user_gifting_reminders',$actions);self::assertStringContainsString("'scheduled'",$actions);self::assertStringContainsString("['scheduled','completed','dismissed','cancelled']",$actions);}
 public function testReminderPreparationConsumesNoExternalAi():void{$context=file_get_contents(dirname(__DIR__,2).'/includes/task-agent-context.php');self::assertIsString($context);self::assertStringNotContainsString('mg_anthropic_messages',$context);self::assertStringNotContainsString('mg_ai_credit_consume',$context);}
}
